PROGRAM ST340_CELL_CONTROL
VAR
    tmr340       : TON;
    tmr350       : TON;
    xBusy1       : BOOL := FALSE;
    xDone1       : BOOL := FALSE;
    xBusy2       : BOOL := FALSE;
    xDone2       : BOOL := FALSE;
    xFull        : BOOL := FALSE;
    xInOpen      : BOOL := FALSE;
    xOutOpen     : BOOL := FALSE;
END_VAR

(* Nodstopp forreglar all drift *)
IF NOT EMG_OK THEN
    xBusy1 := FALSE;
    xDone1 := FALSE;
    xBusy2 := FALSE;
    xDone2 := FALSE;
    xInOpen := FALSE;
    xOutOpen := FALSE;
    xFull := FALSE;
ELSE
    (* Buffertens full-status *)
    xFull := (ST360_BUF_CNT >= 10);

    (* Station 1 (ST340): arbetar 32.0 s *)
    IF ST340_PRT_PRS AND NOT xDone1 THEN
        xBusy1 := TRUE;
    END_IF;

    tmr340(IN := xBusy1, PT := T#32s);

    IF tmr340.Q THEN
        xBusy1 := FALSE;
        xDone1 := TRUE;
    END_IF;

    (* Inloppet till bufferten oppnas nar station 1 ar klar och bufferten inte ar full *)
    xInOpen := xDone1 AND NOT xFull;

    IF NOT ST340_PRT_PRS THEN
        xDone1 := FALSE;
        xInOpen := FALSE;
    END_IF;

    (* Utloppet fran bufferten oppnas nar det finns enheter och station 2 ar ledig *)
    xOutOpen := (ST360_BUF_CNT > 0) AND NOT ST350_PRT_PRS AND NOT xBusy2;

    (* Station 2 (ST350): arbetar 28.0 s *)
    IF ST350_PRT_PRS AND NOT xDone2 THEN
        xBusy2 := TRUE;
    END_IF;

    tmr350(IN := xBusy2, PT := T#28s);

    IF tmr350.Q THEN
        xBusy2 := FALSE;
        xDone2 := TRUE;
    END_IF;

    IF NOT ST350_PRT_PRS THEN
        xDone2 := FALSE;
    END_IF;
END_IF;

ST340_STA_BUSY := xBusy1;
ST340_STA_DONE := xDone1;
ST350_STA_BUSY := xBusy2;
ST350_STA_DONE := xDone2;
ST360_BUF_FULL := xFull;
ST360_STP_IN_OPEN := xInOpen;
ST360_STP_OUT_OPEN := xOutOpen;
END_PROGRAM

